-- ============================================================
-- RevibeK schema v2 -- backup/*.json(RevibeK_AI/backup, 1115건) 적재
--
-- 배경(answer16.md 3장): RevibeK_AI/backup/{video_id}.json은 채널 수집 이력 없이
-- 분석만 된 영상이다. youtube_videos_raw.channel_id, analyzed_songs.youtube_video_raw_id가
-- NOT NULL FK라 그대로 적재할 수 없어, placeholder 채널(BACKUP_IMPORT) 1건을 만들고
-- 그 아래에 1115개 영상을 raw queue로 적재한 뒤 analyzed_songs를 채운다.
-- songs.youtube_id와 일치하는 행만 analyzed_songs.song_id를 채우고(207건),
-- 나머지(908건)는 song_id NULL로 남겨 향후 songs 큐레이션 후보 풀로 둔다.
--
-- id는 모두 uuid5(고정 네임스페이스, 'prefix|video_id')로 생성한 결정적(deterministic) 값이다
-- — 재실행해도 같은 입력이면 같은 id가 나와 INSERT IGNORE가 안전하게 중복을 skip한다.
--
-- 실행 순서: schema_v2_ddl.sql, schema_v2_seed_data.sql, schema_v2_songs_load.sql 다음에 실행
-- (analyzed_songs.song_id가 songs.id를 참조하는 FK라 songs 적재가 먼저 끝나 있어야 한다).
-- ============================================================

USE kpop_radio_2;

-- mysql 클라이언트가 latin1로 접속해 UTF-8 데이터를 이중 인코딩하는 문제 방지(docs/error/error08.md)
SET NAMES utf8mb4;

-- 1) 채널 수집 이력 없이 백업에서만 들어온 영상임을 표시할 placeholder 채널

-- 2) backup/*.json 1115건 전체를 raw queue에 적재 (채널 수집을 거치지 않은 영상)

-- 3) analyzed_songs 적재 -- song_id는 songs.youtube_id와 일치하는 207건만 채워짐

